mapper.select:
SELECT a.order_id, a.order_number, a.application_no, a.status, i.merchant_id, i.invoice_no, i.amount, i.currency,
       CASE WHEN i.status = 'SUCCEEDED' THEN i.amount - COALESCE((
         SELECT SUM(red.amount) FROM invoice_attempts red
         WHERE red.order_id = a.order_id AND red.kind = 'RED' AND red.status = 'SUCCEEDED'
       ), 0) END AS effective_amount
FROM invoice_applications a
LEFT JOIN invoice_attempts i ON i.id = (
  SELECT t.id FROM invoice_attempts t WHERE t.order_id = a.order_id AND t.kind = 'ISSUE' ORDER BY t.id DESC LIMIT 1
)

  AND a.customer_id = #{customerId}
  AND i.merchant_id = #{merchantId} AND i.status = 'SUCCEEDED'
  AND a.status = #{status}

    AND (a.order_number = #{term} OR a.application_no = #{term} OR CAST(a.order_id AS CHAR) = #{term})


ORDER BY a.order_id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE invoice_applications
SET status = #{state}, review_reason = NULL, review_detail = NULL, next_check_at = UTC_TIMESTAMP(6),
    retry_after_id = CASE WHEN #{restartRetries}
      THEN COALESCE((SELECT MAX(t.id) FROM invoice_attempts t WHERE t.order_id = #{orderId}), 0)
      ELSE retry_after_id END
WHERE order_id = #{orderId}

UPDATE invoice_applications SET status = #{status},
  next_check_at = TIMESTAMPADD(MICROSECOND, #{delayMs,jdbcType=INTEGER} * 1000, UTC_TIMESTAMP(6))
WHERE order_id = #{orderId}

UPDATE invoice_applications SET status = 'REVIEW_REQUIRED', review_reason = #{reason},
  review_detail = LEFT(#{detail}, 1024), next_check_at = NULL
WHERE order_id = #{orderId}

UPDATE invoice_applications a SET a.next_check_at = UTC_TIMESTAMP(6)
WHERE a.next_check_at IS NOT NULL AND EXISTS (
  SELECT 1 FROM invoice_attempts t WHERE t.order_id = a.order_id AND t.request_id = #{requestId}
    AND t.status = 'PENDING'
)
